// pauli_cert: exhaustive Pauli-weight distance search for stabilizer codes (CPU + GPU drivers).
//
//   pauli_cert INSTANCE --cap C [--split S] [--gpu 0,1,..] [--threads T] [--chunk K]
//              [--budget B] [--cpu-budget B] [--delta D] [--quiet]
//
// Searches every nontrivial logical of Pauli weight <= C (README.md: algorithm and
// soundness). Output: JSON lines ({"event":"tasks"|"progress"|"round"|"done"}).
//
// Work distribution. The tree is cut at weight S (task = decision path from a
// root, generated by the same core). Tasks run with a node budget; a task that
// exceeds it is abandoned (its partial count discarded) and re-expanded on the
// CPU: its own upper nodes down to weight +D are counted there and the nodes at
// that weight become new tasks (next round). Rounds repeat until no task is
// abandoned. Every node of the tree is therefore counted exactly once; the
// total equals an unsplit run (checked by validate.py).
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <atomic>
#include <chrono>
#include <algorithm>
#include "../common/platform.h"
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <limits>
#include <filesystem>
#include <fcntl.h>
#include <mutex>
#include <thread>
#include "core.h"
#ifndef DMAXW
#define DMAXW 48
#endif

using namespace std;

struct HostCode {
  int n, m, W, C, nl, domain = 0;
  bool greedy = true, trace_enabled = false;
  bool coverage_bound = false;
  int flip_degree = 0;
#ifdef STABCERT_RULES
  int prune = 0;       // opt-in S0/S1/S2 policies (core.h Code::prune; rules build only)
#endif
  vector<uint16_t> gq, qg; vector<uint8_t> gl, gw, ql, qc, qp, L;
  vector<int> orbit, reps;
  Code view() const {
    Code c; c.n = n; c.m = m; c.W = W; c.C = C; c.nl = nl; c.domain = domain;
    c.greedy = greedy; c.trace_enabled = trace_enabled;
    c.coverage_bound = coverage_bound; c.flip_degree = flip_degree;
#ifdef STABCERT_RULES
    c.prune = prune;
#endif
    c.gq = gq.data(); c.gl = gl.data(); c.gw = gw.data(); c.qg = qg.data(); c.ql = ql.data(); c.qc = qc.data(); c.qp = qp.data(); c.L = L.data();
    return c;
  }
};

static void die(const char* m) { fprintf(stderr, "error: %s\n", m); exit(2); }
static void limit(const char* name, int value, int maximum) {
  if (value > maximum) die((string(name) + " exceeded: " + to_string(value) + " > " + to_string(maximum)).c_str());
}

static HostCode load(const char* path) {
  ifstream f(path);
  if (!f) die("cannot open instance");
  HostCode h;
  string first; if (!(f >> first)) die("empty instance");
  bool modern = first == "stabcert-bnb-instance";
  if (modern) {
    int version; if (!(f >> version) || version != 1) die("unsupported instance version");
    if (!(f >> h.n)) die("header n");
  } else {
    size_t used = 0;
    try { h.n = stoi(first, &used); } catch (...) { die("header n"); }
    if (used != first.size()) die("header n");
  }
  if (!(f >> h.m >> h.nl) || h.n < 1 || h.m < 0 || h.nl < 0) die("invalid n/m/nl");
  limit("NMAX", h.n, NMAX); limit("MMAX", h.m, MMAX); limit("nl", h.nl, 2*h.n);
  vector<vector<pair<int,int>>> G(h.m), Lo(h.nl);
  auto rd = [&](vector<vector<pair<int,int>>>& V, bool generators) {
    for (auto& v : V) {
      int r; if (!(f >> r) || r < 0) die("invalid operator weight");
      if (generators) limit("WMAX", r, WMAX);
      limit("operator weight", r, h.n);
      v.resize(r); int previous = -1;
      for (auto& e : v) {
        if (!(f >> e.first >> e.second) || e.first < 0 || e.first >= h.n || e.second < 1 || e.second > 3)
          die("invalid qubit or Pauli label");
        if (e.first <= previous) die("operator qubits must be distinct and ascending");
        previous = e.first;
      }
    }
  };
  rd(G, true); rd(Lo, false);
  h.W = 0; for (auto& g : G) h.W = max(h.W, (int)g.size());
  vector<vector<pair<int,int>>> Q(h.n);
  for (int g = 0; g < h.m; g++) for (auto& e : G[g]) Q[e.first].push_back({g, e.second});
  h.C = 0; for (auto& q : Q) h.C = max(h.C, (int)q.size());
  limit("CMAX", h.C, CMAX);
  h.gq.assign(h.m * h.W, 0); h.gl.assign(h.m * h.W, 0); h.gw.resize(h.m);
  for (int g = 0; g < h.m; g++) { h.gw[g] = G[g].size(); for (size_t p = 0; p < G[g].size(); p++) { h.gq[g * h.W + p] = G[g][p].first; h.gl[g * h.W + p] = G[g][p].second; } }
  h.qg.assign(h.n * h.C, 0); h.ql.assign(h.n * h.C, 0); h.qc.resize(h.n);
  h.qp.assign(h.n * h.C, 0);
  for (int q = 0; q < h.n; q++) { h.qc[q] = Q[q].size(); for (size_t j = 0; j < Q[q].size(); j++) { h.qg[q * h.C + j] = Q[q][j].first; h.ql[q * h.C + j] = Q[q][j].second; } }
  for (int g = 0; g < h.m; g++) for (int p = 0; p < h.gw[g]; p++) { int q = h.gq[g * h.W + p]; for (int j = 0; j < h.qc[q]; j++) if (h.qg[q * h.C + j] == g) h.qp[q * h.C + j] = p; }
  h.L.assign((size_t)h.nl * h.n, 0);
  for (int l = 0; l < h.nl; l++) for (auto& e : Lo[l]) h.L[(size_t)l * h.n + e.first] = e.second;
  h.orbit.resize(h.n); for (auto& o : h.orbit) if (!(f >> o)) die("orbit");
  int no; if (!(f >> no) || no < 1 || no > h.n) die("invalid orbit count");
  h.reps.resize(no);
  for (int oi = 0; oi < no; oi++) {
    int& r = h.reps[oi];
    if (!(f >> r) || r < 0 || r >= h.n || h.orbit[r] != oi) die("invalid orbit representative");
  }
  for (auto o : h.orbit) if (o < 0 || o >= no) die("invalid orbit index");
  if (modern) {
    string tag, domain;
    if (!(f >> tag >> domain) || tag != "domain" || (domain != "P" && domain != "X" && domain != "Z"))
      die("expected domain P|X|Z");
    h.domain = domain == "X" ? 1 : domain == "Z" ? 2 : 0;
  }
  string extra; if (f >> extra) die("unexpected trailing input (rootmask is not supported)");
  for(int q=0;q<h.n;q++) for(int l=1;l<=3;l++) if(!h.domain || h.domain==l) {
    int flips=0;
    for(int j=0;j<h.qc[q];j++) flips += h.ql[q*h.C+j]!=l;
    h.flip_degree=max(h.flip_degree,flips);
  }
  return h;
}

// A batch of tasks: root code ((orbit << 2) | label) and a decision path (fixed stride).
static int g_stop_first = 0;   // --stop-first: the first find sets the cap to 0 (everything stops)

struct Batch {
  int stride = 1;
  vector<uint32_t> root; vector<uint8_t> len; vector<uint8_t> path;
  long long count() const { return root.size(); }
  void add(uint32_t r, const uint8_t* p, int l) {
    if (l > stride) die("path longer than batch stride");
    root.push_back(r); len.push_back((uint8_t)l);
    size_t o = path.size(); path.resize(o + stride, 0); if (l) memcpy(path.data() + o, p, l);
  }
};

struct Found { int w = 1 << 30; vector<pair<int,int>> wit; };

static void take_found(const Dfs& st, Found& F) {
  if (st.last_found_w > 0 && st.last_found_w < F.w) {
    F.w = st.last_found_w; F.wit.clear();
    for (int i = 0; i < st.nwit; i++) F.wit.push_back({st.wq[i], st.wl[i]});
  }
}

// Expand the node (root r, path p[0..len)) down to weight `split`: counts the
// nodes above `split` (the task node included), emits the weight-`split` nodes.
// Returns -1 if the replay failed (must not happen).
static long long expand(const Code& c, const HostCode& h, int cap0, uint32_t r, const uint8_t* p, int len, int split,
                        vector<uint8_t>& out, Found& found) {
  Dfs* st = new Dfs; st->init(c, cap0);
  int oi = r >> 2, l = r & 3;
  long long nd = 0;
  if (st->root(c, h.orbit.data(), h.reps[oi], oi, l)) {
    if (!st->replay(c, p, len)) { delete st; return -1; }
    int base = st->depth, f = -1;
    if (st->w >= split) die("expand: node already at split weight");
#ifdef STABCERT_RULES
    if (st->enter_any(c, &f)) {
#else
    if (st->enter(c, &f)) {
#endif
      while (st->depth > base) {
        if (st->next_child(c)) {
          if (st->w == split) {
            for (int d = 0; d < st->depth; d++) out.push_back((uint8_t)((st->fr[d].pos << 1) | (st->fr[d].li - 1)));
            st->undo_child(c);
            continue;
          }
          f = -1;
#ifdef STABCERT_RULES
          if (!st->enter_any(c, &f)) st->undo_child(c);
#else
          if (!st->enter(c, &f)) st->undo_child(c);
#endif
          continue;
        }
        st->unmodify(c, st->fr[st->depth - 1]);
        st->depth--;
        if (st->depth > base) st->undo_child(c);
      }
    }
    nd = st->nodes;
    take_found(*st, found);
  }
  delete st;
  return nd;
}

// Expand a list of (root, path) nodes in parallel into a new batch.
static Batch expand_all(const HostCode& h, int cap0, const vector<uint32_t>& roots, const vector<vector<uint8_t>>& paths,
                        const vector<int>& splits, int threads, long long& nodes, long long& rfail, Found& found) {
  Code c = h.view();
  int N = roots.size();
  vector<vector<uint8_t>> outs(N);
  vector<long long> nd(N);
  vector<Found> pf(N);
  #pragma omp parallel for schedule(dynamic, 1) num_threads(threads)
  for (int i = 0; i < N; i++) nd[i] = expand(c, h, cap0, roots[i], paths[i].data(), paths[i].size(), splits[i], outs[i], pf[i]);
  Batch B;
  for (int i = 0; i < N; i++) B.stride = max(B.stride, splits[i] - 1);
  for (int i = 0; i < N; i++) {
    if (nd[i] < 0) { rfail++; continue; }
    nodes += nd[i];
    if (pf[i].w < found.w) found = pf[i];
    int pl = splits[i] - 1;
    for (size_t o = 0; o + pl <= outs[i].size() && pl > 0; o += pl) B.add(roots[i], outs[i].data() + o, pl);
  }
  return B;
}

// ---------------------------------------------------------------------------
// CPU executor: tnodes[t] = subtree nodes, or -1 if the budget was exceeded
// ---------------------------------------------------------------------------
static void run_cpu(const HostCode& h, const Batch& T, int cap0, long long t0, long long t1, int threads, std::atomic<int>& gcap,
                    vector<long long>& tnodes, long long& replay_fail, Found& found, long long budget,
                    vector<uint64_t>* traces = nullptr) {
  Code c = h.view();
  long long rf = 0;
  vector<Found> pf(threads);
  #pragma omp parallel num_threads(threads) reduction(+:rf)
  {
    Dfs* st = new Dfs;
    int tid = omp_get_thread_num();
    #pragma omp for schedule(dynamic, 1)
    for (long long t = t0; t < t1; t++) {
      st->init(c, cap0);                     // replay under the generation cap (exact reproduction)
      int oi = T.root[t] >> 2, l = T.root[t] & 3;
      long long nd = 0;
      if (st->root(c, h.orbit.data(), h.reps[oi], oi, l)) {
        if (!st->replay(c, T.path.data() + t * T.stride, T.len[t])) rf++;
        else {
          st->cap = min(cap0, gcap.load());   // then search under the current (possibly lowered) cap
          int b = st->run(c, [&]() { return gcap.load(); }, budget);
          if (b < (1 << 30)) {
            STABCERT_CHECKPOINT_HOOK("cpu-find-returned");
            int cur = gcap.load();
            int nc = g_stop_first ? 0 : b - 1;
            while (nc < cur && !gcap.compare_exchange_weak(cur, nc)) {}
            STABCERT_CHECKPOINT_HOOK("cpu-cap-published");
            take_found(*st, pf[tid]);
            STABCERT_CHECKPOINT_HOOK("cpu-find-copied");
          }
        }
        nd = st->aborted ? -1 : st->nodes;
      }
      tnodes[t - t0] = nd;
      if (traces) (*traces)[t-t0] = st->trace;
    }
    delete st;
  }
  replay_fail += rf;
  for (auto& f : pf) if (f.w < found.w) found = f;
}

// ---------------------------------------------------------------------------
// GPU executor (warp-cooperative kernel, warp.cuh)
// ---------------------------------------------------------------------------
#ifdef __CUDACC__
#include <cuda_runtime.h>
#include "warp.cuh"
#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) { fprintf(stderr, "CUDA %s at %s:%d\n", cudaGetErrorString(e_), __FILE__, __LINE__); exit(3); } } while (0)

template <class T> static T* up(const vector<T>& v) { T* d; CK(cudaMalloc(&d, max<size_t>(1, v.size()) * sizeof(T))); if (!v.empty()) CK(cudaMemcpy(d, v.data(), v.size() * sizeof(T), cudaMemcpyHostToDevice)); return d; }

struct Gpu {
  int dev; Code c; int *orbit, *reps; unsigned long long* next; int* gcap; int* rfail; int *bw, *bn, *errflag;
  int nwarps, blocks, tpb; size_t wbytes, smem;
  uint32_t* troot = nullptr; uint8_t *tlen = nullptr, *tpath = nullptr; long long* tnodes = nullptr; long long a = 0, b = 0;
  uint64_t* ttraces = nullptr;
  cudaStream_t st; long long capT = 0; int capS = 0;   // own non-blocking stream; buffers grown, never freed per chunk
};

static Gpu gpu_setup(int dev, const HostCode& h, int tpb, int bps) {
  if (h.W > 32 || h.C > 64) die("warp kernel needs W <= 32 and C <= 64");
  Gpu g; g.dev = dev; CK(cudaSetDevice(dev));
  // Later slots reuse this context; configure waiting only on the first slot.
  static vector<int> blocking_devices;
  if (find(blocking_devices.begin(), blocking_devices.end(), dev) == blocking_devices.end()) {
    CK(cudaSetDeviceFlags(cudaDeviceScheduleBlockingSync));
    blocking_devices.push_back(dev);
  }
  cudaDeviceProp p; CK(cudaGetDeviceProperties(&p, dev));
  size_t per_warp = WarpDfs::bytes(h.n, h.m, h.coverage_bound);
  size_t shared_limit = p.sharedMemPerBlockOptin ? p.sharedMemPerBlockOptin : p.sharedMemPerBlock;
  while (tpb > 32 && per_warp * (tpb / 32) > shared_limit) tpb -= 32;
  if (per_warp > shared_limit) die(("CUDA shared memory limit: n=" + to_string(h.n) + " m=" + to_string(h.m) + " bytes=" + to_string(per_warp) + " available=" + to_string(shared_limit)).c_str());
  g.tpb = tpb; g.blocks = p.multiProcessorCount * bps; g.nwarps = g.blocks * tpb / 32;
  g.c = h.view();
  g.c.gq = up(h.gq); g.c.gl = up(h.gl); g.c.gw = up(h.gw); g.c.qg = up(h.qg); g.c.ql = up(h.ql); g.c.qc = up(h.qc); g.c.qp = up(h.qp); g.c.L = up(h.L);
  g.orbit = up(h.orbit); g.reps = up(h.reps);
  CK(cudaMalloc(&g.next, sizeof(unsigned long long))); CK(cudaMalloc(&g.gcap, sizeof(int))); CK(cudaMalloc(&g.rfail, sizeof(int)));
  CK(cudaMalloc(&g.errflag, sizeof(int))); CK(cudaMemset(g.errflag, 0, sizeof(int)));
  CK(cudaMalloc(&g.bw, g.nwarps * sizeof(int))); CK(cudaMalloc(&g.bn, g.nwarps * sizeof(int)));
  g.wbytes = WarpDfs::bytes(h.n, h.m, h.coverage_bound); g.smem = g.wbytes * (tpb / 32);
  CK(cudaFuncSetAttribute(kern_warp, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g.smem));
  CK(cudaStreamCreateWithFlags(&g.st, cudaStreamNonBlocking));
  return g;
}

static void gpu_start(Gpu& g, const Batch& T, long long a, long long b, int cap0, int capnow, long long budget) {
  CK(cudaSetDevice(g.dev));
  long long nt = b - a; g.a = a; g.b = b;
  if (nt > g.capT || T.stride > g.capS) {
    for (void* p : {(void*)g.troot, (void*)g.tlen, (void*)g.tpath, (void*)g.tnodes, (void*)g.ttraces}) if (p) CK(cudaFree(p));
    g.capT = max(nt, g.capT); g.capS = max(T.stride, g.capS);
    CK(cudaMalloc(&g.troot, g.capT * sizeof(uint32_t))); CK(cudaMalloc(&g.tlen, g.capT));
    CK(cudaMalloc(&g.tpath, g.capT * g.capS)); CK(cudaMalloc(&g.tnodes, g.capT * sizeof(long long)));
    if (g.c.trace_enabled) CK(cudaMalloc(&g.ttraces, g.capT * sizeof(uint64_t)));
  }
  CK(cudaMemcpyAsync(g.troot, T.root.data() + a, nt * sizeof(uint32_t), cudaMemcpyHostToDevice, g.st));
  CK(cudaMemcpyAsync(g.tlen, T.len.data() + a, nt, cudaMemcpyHostToDevice, g.st));
  CK(cudaMemcpyAsync(g.tpath, T.path.data() + a * T.stride, nt * T.stride, cudaMemcpyHostToDevice, g.st));
  CK(cudaMemsetAsync(g.next, 0, sizeof(unsigned long long), g.st));
  CK(cudaMemcpyAsync(g.gcap, &capnow, sizeof(int), cudaMemcpyHostToDevice, g.st));
  CK(cudaMemsetAsync(g.rfail, 0, sizeof(int), g.st));
  vector<int> big(g.nwarps, 1 << 30); CK(cudaMemcpyAsync(g.bw, big.data(), g.nwarps * sizeof(int), cudaMemcpyHostToDevice, g.st));
  CK(cudaStreamSynchronize(g.st));            // host buffers above are locals / may move: finish the copies first
  kern_warp<<<g.blocks, g.tpb, g.smem, g.st>>>(g.c, cap0, g.orbit, g.reps, g.troot, g.tlen, g.tpath, T.stride, 0, nt, g.next, g.gcap,
                                         g.tnodes, g.ttraces, g.rfail, g.bw, g.bn, g.errflag, g.wbytes, budget, g_stop_first);
  CK(cudaGetLastError());
}

// wait, collect node counts, cap, finds (witness re-derived by re-running the task on the CPU core)
static void gpu_finish(Gpu& g, const HostCode& h, const Batch& T, int cap0, long long c0, vector<long long>& tn,
                       std::atomic<int>& gcap, long long& rfail, Found& found, vector<uint64_t>* traces = nullptr) {
  if (g.b <= g.a) return;
  CK(cudaSetDevice(g.dev)); CK(cudaStreamSynchronize(g.st));
  long long nt = g.b - g.a;
  int rf, gc, ef;
  CK(cudaMemcpyAsync(tn.data() + (g.a - c0), g.tnodes, nt * sizeof(long long), cudaMemcpyDeviceToHost, g.st));
  if (traces) CK(cudaMemcpyAsync(traces->data() + (g.a-c0), g.ttraces, nt * sizeof(uint64_t), cudaMemcpyDeviceToHost, g.st));
  CK(cudaMemcpyAsync(&rf, g.rfail, sizeof(int), cudaMemcpyDeviceToHost, g.st));
  CK(cudaMemcpyAsync(&ef, g.errflag, sizeof(int), cudaMemcpyDeviceToHost, g.st));
  CK(cudaStreamSynchronize(g.st)); rfail += rf;
  if (ef) { fprintf(stderr, "warp kernel error flag %d\n", ef); die("warp kernel overflow (LMAX/DMAXW)"); }
  CK(cudaMemcpyAsync(&gc, g.gcap, sizeof(int), cudaMemcpyDeviceToHost, g.st)); CK(cudaStreamSynchronize(g.st));
  if (gc < cap0) STABCERT_CHECKPOINT_HOOK("gpu-find-returned");
  int cur = gcap.load(); while (gc < cur && !gcap.compare_exchange_weak(cur, gc)) {}
  if (gc < cap0) STABCERT_CHECKPOINT_HOOK("gpu-cap-published");
  vector<int> bw(g.nwarps), bn(g.nwarps);
  CK(cudaMemcpyAsync(bw.data(), g.bw, g.nwarps * sizeof(int), cudaMemcpyDeviceToHost, g.st));
  CK(cudaMemcpyAsync(bn.data(), g.bn, g.nwarps * sizeof(int), cudaMemcpyDeviceToHost, g.st));
  CK(cudaStreamSynchronize(g.st));
  int bt = -1; for (int t = 0; t < g.nwarps; t++) if (bw[t] < found.w && (bt < 0 || bw[t] < bw[bt])) bt = t;
  if (bt >= 0) {
    long long tk = g.a + bn[bt]; vector<long long> tn1(1); long long rf1 = 0; Found f1; std::atomic<int> gc1(bw[bt]);
    run_cpu(h, T, cap0, tk, tk + 1, 1, gc1, tn1, rf1, f1, 1LL << 62);
    if (f1.w <= bw[bt]) found = f1; else { fprintf(stderr, "CPU re-run of a GPU find did not reproduce it\n"); exit(5); }
    STABCERT_CHECKPOINT_HOOK("gpu-find-copied");
  }
}
#endif

static double now() { return chrono::duration<double>(chrono::steady_clock::now().time_since_epoch()).count(); }

#include "checkpoint.h"

static long long integer(const string& value) {
  size_t end = 0; long long result = stoll(value, &end);
  if (end != value.size()) die("invalid integer argument");
  return result;
}
static int small_integer(const string& value) {
  long long result = integer(value);
  if (result < numeric_limits<int>::min() || result > numeric_limits<int>::max()) die("integer argument out of range");
  return (int)result;
}
static bool digest_ok(const string& value) {
  return value.size() == 64 && value.find_first_not_of("0123456789abcdef") == string::npos;
}

#include "coverage.h"

static int main_impl(int argc, char** argv) {
  if (argc == 2 && string(argv[1]) == "--version") {
    char limits[256];
#ifdef STABCERT_RULES
    // The rules build also lists its opt-in rule set (Python checks it before using those policies).
    snprintf(limits, sizeof limits, "{\"NMAX\":%d,\"MMAX\":%d,\"WMAX\":%d,\"CMAX\":%d,\"DMAXW\":%d,\"RULES\":\"s0s1s2/1\"}", NMAX, MMAX, WMAX, CMAX, DMAXW);
#else
    snprintf(limits, sizeof limits, "{\"NMAX\":%d,\"MMAX\":%d,\"WMAX\":%d,\"CMAX\":%d,\"DMAXW\":%d}", NMAX, MMAX, WMAX, CMAX, DMAXW);
#endif
#ifdef __CUDACC__
    stabcert::version("stabcert-bnb-cuda", limits);
#else
    stabcert::version("stabcert-bnb", limits);
#endif
    return 0;
  }
  if (argc < 2) { fprintf(stderr, "usage: pauli_cert INSTANCE --cap C [--split S] [--gpu 0,1] [--threads T] [--chunk K] [--budget B] [--cpu-budget B] [--delta D]\n"); return 2; }
  const char* inst = argv[1];
  int cap = -1, split = 1, threads = omp_get_max_threads(), tpb = 256, bps = 8, delta = 3;
  long long chunk = 2000000, budget = 2000000, cpubudget = 200000000;
  string gpus, ckpt, instance_sha, binary_sha, bound = "greedy"; bool quiet = false; int cpuworker = 0, slots = 2;
  string cert, cert_metadata, cert_detail = "frontier"; int cert_version = 1;
  for (int i = 2; i < argc; i++) {
    string a = argv[i];
    auto nx = [&]() { if (i + 1 >= argc) die("missing value"); return string(argv[++i]); };
    if (a == "--cap") cap = small_integer(nx());
    else if (a == "--split") split = small_integer(nx());
    else if (a == "--threads") threads = small_integer(nx());
    else if (a == "--gpu") gpus = nx();
    else if (a == "--chunk") chunk = integer(nx());
    else if (a == "--budget") budget = integer(nx());
    else if (a == "--cpu-budget") cpubudget = integer(nx());
    else if (a == "--delta") delta = small_integer(nx());
    else if (a == "--tpb") tpb = small_integer(nx());
    else if (a == "--bps") bps = small_integer(nx());
    else if (a == "--quiet") quiet = true;
    else if (a == "--cpu-worker") cpuworker = small_integer(nx());
    else if (a == "--ckpt") ckpt = nx();
    else if (a == "--instance-sha256") instance_sha = nx();
    else if (a == "--binary-sha256") binary_sha = nx();
    else if (a == "--bound") bound = nx();
    else if (a == "--emit-cert") cert = nx();
    else if (a == "--cert-metadata") cert_metadata = nx();
    else if (a == "--cert-detail") cert_detail = nx();
    else if (a == "--cert-version") cert_version = small_integer(nx());
    else if (a == "--slots") slots = small_integer(nx());   // kernels in flight per GPU (overlaps chunk tails)
    else if (a == "--stop-first") g_stop_first = 1;
    else if (a == "--warp") {}
    else die(("unknown option " + a).c_str());
  }
  if ((!instance_sha.empty() && !digest_ok(instance_sha)) || (!binary_sha.empty() && !digest_ok(binary_sha)))
    die("SHA256 arguments must contain 64 lowercase hexadecimal digits");
  if (!ckpt.empty() && (instance_sha.empty() || binary_sha.empty()))
    die("--ckpt requires --instance-sha256 and --binary-sha256 computed by the caller");
#ifdef STABCERT_RULES
  // Opt-in S0/S1/S2 policies (SOUNDNESS.md 5.1): CPU only, count-only (no coverage certificate v1).
  int prune = bound == "greedy+s0" ? 1 : bound == "greedy+s0s1" ? 2 : bound == "greedy+s0s1s2" ? 3 : 0;
  if (bound != "greedy" && bound != "none" && bound != "greedy+b1b3" && !prune)
    die("--bound must be none, greedy, greedy+b1b3, greedy+s0, greedy+s0s1 or greedy+s0s1s2");
  if (prune && !gpus.empty()) die("--bound greedy+s0/greedy+s0s1/greedy+s0s1s2 is CPU-only; it cannot be combined with --gpu");
  if (bound != "greedy" && !prune && !ckpt.empty()) {
    // Version 2 checkpoints use greedy packing or one of the opt-in rule policies (then bound into the
    // header as " bound=<policy>"). Any other policy is a rejected resume, not a new search; never open
    // the old file for writing.
    if (std::filesystem::exists(ckpt))
      checkpoint_error("bound policy mismatch (version 2 requires greedy or greedy+s0/greedy+s0s1/greedy+s0s1s2)");
    die("--bound none and greedy+b1b3 are incompatible with version-2 checkpoints");
  }
#else
  if (bound != "greedy" && bound != "none" && bound != "greedy+b1b3") die("--bound must be none, greedy or greedy+b1b3");
  if (bound != "greedy" && !ckpt.empty()) {
    // Version 2 checkpoints always use greedy packing. A different policy is
    // a rejected resume, not a new search; never open the old file for writing.
    if (std::filesystem::exists(ckpt)) checkpoint_error("bound policy mismatch (version 2 requires greedy)");
    die("nondefault --bound is incompatible with version-2 checkpoints");
  }
#endif
  int requested_stop_first = g_stop_first;
  if (!ckpt.empty()) g_stop_first = 1;
  if (cap < 0) die("--cap must be nonnegative");
  limit("DMAXW-2 (cap)", cap, DMAXW-2);
  if (split == 0 || split == numeric_limits<int>::min()) die("--split must be positive or a negative task target");
  limit("DMAXW-1 (split)", split, DMAXW-1);
  if (threads < 1 || cpuworker < 0 || chunk < 1 || budget < 1 || cpubudget < 1 || delta < 1 || delta > DMAXW || slots < 1 || bps < 1 || tpb < 32 || tpb > 1024 || tpb % 32)
    die("invalid threads/chunk/budget/delta/slots/bps/tpb");
#ifndef _OPENMP
  threads = 1; if (cpuworker) cpuworker = 1;
#endif
#ifndef __CUDACC__
  if (!gpus.empty()) die("built without CUDA");
#endif
  double T0 = now();
  HostCode h = load(inst);
  h.greedy = bound != "none";
  h.coverage_bound = bound == "greedy+b1b3";
#ifdef STABCERT_RULES
  h.prune = prune;
#endif
  if (!cert.empty()) {
    if (instance_sha.empty() || binary_sha.empty() || cert_metadata.empty())
      die("--emit-cert requires --cert-metadata, --instance-sha256 and --binary-sha256");
    if (cert_version != 1 && cert_version != 2) die("--cert-version must be 1 or 2");
    // Version 1 admits only greedy; version 2 (docs/BNB_CERT_SPEC_v2.md) also the opt-in S0/S1/S2 policies.
    bool v2_rules = false;
#ifdef STABCERT_RULES
    v2_rules = cert_version == 2 && prune;
#endif
    if (!ckpt.empty() || requested_stop_first || (bound != "greedy" && !v2_rules))
      die("--emit-cert is incompatible with --ckpt, --stop-first and nondefault --bound (version 2 also admits greedy+s0, greedy+s0s1 and greedy+s0s1s2)");
    if (cert_detail != "frontier" && cert_detail != "full") die("--cert-detail must be frontier or full");
    if (split < 0) {
      long long target = -(long long)split;
      vector<uint32_t> roots; vector<vector<uint8_t>> paths;
      for (int oi=0;cap>0 && oi<(int)h.reps.size();oi++) for(int l=1;l<=3;l++) if(!h.domain || h.domain==l) {
        roots.push_back((oi<<2)|l);paths.push_back({});
      }
      for(split=2;;split++) {
        long long nodes=0,rf=0;Found f;vector<int> cuts(roots.size(),split);
        Batch trial=expand_all(h,cap,roots,paths,cuts,threads,nodes,rf,f);
        if(rf)die("certificate automatic split replay failed");
        if(trial.count()>=target || split>=cap || !trial.count())break;
      }
    }
    CovOptions o;
    o.output=cert;o.metadata=cert_metadata;o.detail=cert_detail;o.version=cert_version;
    o.rules=bound=="greedy"?"greedy":bound.substr(strlen("greedy+"));o.instance=inst;o.instance_sha=instance_sha;o.binary_sha=binary_sha;o.gpus=gpus;
    o.cap=cap;o.split=split;o.threads=threads;o.tpb=tpb;o.bps=bps;o.delta=delta;o.slots=slots;
    o.chunk=chunk;o.budget=budget;o.cpu_budget=cpubudget;o.quiet=quiet;
    return emit_coverage(h,o);
  }
  if (!cert_metadata.empty() || cert_detail != "frontier" || cert_version != 1) die("certificate options require --emit-cert");
  long long gen_nodes = 0, rfail = 0, tot = 0, maxt = 0, aborted_total = 0, tasks_total = 0; Found found;
  // roots
  vector<uint32_t> roots; vector<vector<uint8_t>> paths; vector<int> splits;
  for (int oi = 0; cap > 0 && oi < (int)h.reps.size(); oi++) for (int l = 1; l <= 3; l++) if (!h.domain || h.domain == l) {
    roots.push_back(((uint32_t)oi << 2) | (uint32_t)l); paths.push_back({}); splits.push_back(max(split, 2));
  }
  Batch T;
  if (split < 0) {                         // auto: smallest split >= 2 giving >= -split tasks
    long long target = -split;
    for (split = 2;; split++) {
      for (auto& x : splits) x = split;
      gen_nodes = 0; found = Found();
      T = expand_all(h, cap, roots, paths, splits, threads, gen_nodes, rfail, found);
      if (T.count() >= target || split >= cap || T.count() == 0) break;
    }
  } else if (split <= 1) { for (auto r : roots) T.add(r, nullptr, 0); }
  else T = expand_all(h, cap, roots, paths, splits, threads, gen_nodes, rfail, found);
  printf("{\"event\":\"tasks\",\"n\":%d,\"m\":%d,\"nl\":%d,\"W\":%d,\"C\":%d,\"orbits\":%zu,\"roots\":%zu,\"cap\":%d,\"split\":%d,\"ntasks\":%lld,\"gen_nodes\":%lld,\"gen_found\":%d,\"gen_sec\":%.3f}\n",
         h.n, h.m, h.nl, h.W, h.C, h.reps.size(), roots.size(), cap, split, T.count(), gen_nodes, found.w < (1 << 30) ? found.w : -1, now() - T0);
  fflush(stdout);
  std::atomic<int> gcap(found.w < (1 << 30) ? min(cap, found.w - 1) : cap);
#ifdef __CUDACC__
  vector<Gpu> G;
  if (!gpus.empty()) {
    size_t p = 0; while (p < gpus.size()) { size_t q = gpus.find(',', p); if (q == string::npos) q = gpus.size(); for (int sl = 0; sl < slots; sl++) G.push_back(gpu_setup(stoi(gpus.substr(p, q - p)), h, tpb, bps)); p = q + 1; }
  }
#else
  if (!gpus.empty()) die("built without CUDA");
#endif
#ifdef __CUDACC__
  bool G_empty = G.empty();
#else
  bool G_empty = true;
#endif
  string domain = h.domain == 1 ? "X" : h.domain == 2 ? "Z" : "P";
  ostringstream header;
  header << "H stabcert-bnb-ckpt 2 instance_sha256=" << instance_sha << " domain=" << domain
         << " cap=" << cap << " split=" << split << " delta=" << delta
         << " stop_first=" << requested_stop_first << " source_sha256=" << STABCERT_SOURCE_SHA256
         << " binary_sha256=" << binary_sha << " gen_tasks=" << T.count();
#ifdef STABCERT_RULES
  // The opt-in policies are bound into the header; greedy headers are unchanged, so a greedy checkpoint
  // and a greedy+s0* checkpoint can never resume each other (header mismatch -> exit 6).
  if (prune) header << " bound=" << bound;
#endif
  Checkpoint checkpoint(ckpt, header.str(), cap, h.n, h.domain);
  validate_checkpoint(h, T, checkpoint, cap, delta, threads);
  auto& prev = checkpoint.previous;
  bool saved_find = checkpoint.saved_find.w < (1 << 30);
  if (saved_find) {
    found = checkpoint.saved_find;
    gen_nodes = 0; // F records preserve a witness, not schedule-dependent partial node totals.
    checkpoint.activate();
  } else {
    checkpoint.activate();
    if (found.w < (1 << 30)) checkpoint.find(found);
  }
  if (g_stop_first && found.w < (1 << 30)) gcap.store(0);
  int round = 0;
  while (T.count() > 0 && !(g_stop_first && found.w < (1 << 30))) {
    tasks_total += T.count();
    vector<uint32_t> ar; vector<vector<uint8_t>> ap; vector<int> as;
    long long rnodes = 0;
    // Dynamic work queue: one host thread per GPU slot (+ optional CPU worker).
    std::mutex mu;
    long long NT = T.count();
    vector<char> done(NT, 0);
    if ((int)prev.size() > round) for (auto& p : prev[round]) {
      for (long long t = p.a; t < p.b; t++) done[t] = 1;
      tot += p.nodes; rnodes += p.nodes; maxt = max(maxt, p.maxn); rfail += p.rf; aborted_total += p.ab.size();
      for (long long t : p.ab) {
        ar.push_back(T.root[t]);
        ap.push_back(vector<uint8_t>(T.path.begin() + t * T.stride, T.path.begin() + t * T.stride + T.len[t]));
        as.push_back(T.len[t] + 1 + delta);
      }
    }
    long long round_chunk = chunk;
#ifdef __CUDACC__
    if (!G.empty()) {
      // Keep several pieces per slot even when a round fits in --chunk.
      // Splitting only changes ownership of tasks, never their search state.
      const long long target_pieces = (long long)G.size() * 4;
      round_chunk = min(chunk, 1 + (NT - 1) / target_pieces);
    }
#endif
    vector<pair<long long,long long>> pieces;
    for (long long t = 0; t < NT;) {
      if (done[t]) { t++; continue; }
      long long b = t; while (b < NT && !done[b] && b - t < round_chunk) b++;
      pieces.push_back({t, b}); t = b;
    }
    std::atomic<long long> nextp(0);
    auto consume = [&](long long a, long long b, vector<long long>& tn, long long rf, const Found& fl, double tc, const char* who) {
      if (fl.w < (1 << 30)) STABCERT_CHECKPOINT_HOOK("before-find-consume");
      std::lock_guard<std::mutex> lk(mu);
      if (checkpoint.has_file() && found.w < (1 << 30)) return;
      rfail += rf;
      if (fl.w < found.w) found = fl;
      if (fl.w < (1 << 30)) STABCERT_CHECKPOINT_HOOK("find-adopted");
      if (g_stop_first && found.w < (1 << 30)) gcap.store(0);
      long long cs = 0, cm = 0, na = 0;
      for (long long t = a; t < b; t++) {
        long long x = tn[t - a];
        if (x < 0) {
          na++; ar.push_back(T.root[t]);
          ap.push_back(vector<uint8_t>(T.path.begin() + t * T.stride, T.path.begin() + t * T.stride + T.len[t]));
          as.push_back(T.len[t] + 1 + delta);
        } else { cs += x; cm = max(cm, x); }
      }
      tot += cs; rnodes += cs; maxt = max(maxt, cm); aborted_total += na;
      if (checkpoint.has_file()) {
        // The same mutex protects F persistence and every C append. No C is
        // written for this finding piece, and later consumers return above.
        if (found.w < (1 << 30)) checkpoint.find(found);
        else {
          ostringstream record;
          record << "C " << round << ' ' << a << ' ' << b << ' ' << cs << ' ' << cm << ' ' << rf << ' ' << na;
          for (long long t = a; t < b; t++) if (tn[t-a] < 0) record << ' ' << t;
          checkpoint.append(record.str());
        }
      }
      if (fl.w < (1 << 30)) STABCERT_CHECKPOINT_HOOK("before-find-progress");
      if (!quiet) {
        printf("{\"event\":\"progress\",\"round\":%d,\"worker\":\"%s\",\"task_start\":%lld,\"task_end\":%lld,\"round_tasks\":%lld,\"chunk_nodes\":%lld,\"chunk_aborted\":%lld,\"chunk_max_task_nodes\":%lld,\"chunk_sec\":%.3f,\"cap\":%d,\"found\":%d,\"replay_fail\":%lld,\"total_nodes\":%lld,\"elapsed\":%.1f}\n",
               round, who, a, b, NT, cs, na, cm, now() - tc, gcap.load(), found.w < (1 << 30) ? found.w : -1, rfail, tot + gen_nodes, now() - T0);
        fflush(stdout);
      }
      if (fl.w < (1 << 30)) STABCERT_CHECKPOINT_HOOK("after-find-progress");
    };
    vector<std::thread> workers;
#ifdef __CUDACC__
    for (size_t i = 0; i < G.size(); i++) workers.emplace_back([&, i]() {
      char who[16]; snprintf(who, sizeof who, "gpu%d", G[i].dev);
      while (true) {
        if (g_stop_first && gcap.load() == 0) break;
        long long pi = nextp.fetch_add(1); if (pi >= (long long)pieces.size()) break;
        long long a = pieces[pi].first, b = pieces[pi].second;
        double tc = now(); vector<long long> tn(b - a); long long rf = 0; Found fl;
        G[i].a = a; G[i].b = b;
        gpu_start(G[i], T, a, b, cap, gcap.load(), budget);
        gpu_finish(G[i], h, T, cap, a, tn, gcap, rf, fl);
        consume(a, b, tn, rf, fl, tc, who);
      }
    });
#endif
    if (G_empty || cpuworker > 0) workers.emplace_back([&]() {
      int th = G_empty ? threads : cpuworker;
      while (true) {
        if (g_stop_first && gcap.load() == 0) break;
        long long pi = nextp.fetch_add(1); if (pi >= (long long)pieces.size()) break;
        long long a = pieces[pi].first, b = pieces[pi].second;
        double tc = now(); vector<long long> tn(b - a); long long rf = 0; Found fl;
        run_cpu(h, T, cap, a, b, th, gcap, tn, rf, fl, cpubudget);
        consume(a, b, tn, rf, fl, tc, "cpu");
      }
    });
    for (auto& t : workers) t.join();
    if (g_stop_first && found.w < (1 << 30)) { round++; break; }
    // re-expand abandoned tasks (their upper part counted as generator nodes)
    double te = now();
    for (auto& s : as) s = min(s, cap);       // a node at weight cap has no expandable children
    long long gn0 = gen_nodes;
    Batch N = expand_all(h, cap, ar, ap, as, threads, gen_nodes, rfail, found);
    if (found.w < (1 << 30)) checkpoint.find(found);
    if (!quiet) {
      printf("{\"event\":\"round\",\"round\":%d,\"tasks\":%lld,\"task_nodes\":%lld,\"aborted\":%zu,\"reexpand_nodes\":%lld,\"new_tasks\":%lld,\"reexpand_sec\":%.2f,\"elapsed\":%.1f}\n",
             round, T.count(), rnodes, ar.size(), gen_nodes - gn0, N.count(), now() - te, now() - T0);
      fflush(stdout);
    }
    if (g_stop_first && found.w < (1 << 30)) gcap.store(0);
    T = std::move(N);
    round++;
  }
  checkpoint.close();
  string hash_json = instance_sha.empty() ? "null" : "\"" + instance_sha + "\"";
  const char* executor = G_empty ? "cpu" : cpuworker ? "mixed" : "gpu";
  if (found.w < (1 << 30)) STABCERT_CHECKPOINT_HOOK("before-find-done");
  printf("{\"event\":\"done\",\"interface\":1,\"instance_sha256\":%s,\"domain\":\"%s\",\"delta\":%d,\"executor\":\"%s\",\"resumed\":%s,\"stopped_on_find\":%s,", hash_json.c_str(), domain.c_str(), delta, executor, stabcert::json_bool(checkpoint.resumed), stabcert::json_bool(g_stop_first && found.w < (1 << 30)));
  printf("\"bound\":\"%s\",\"cap0\":%d,\"split\":%d,\"rounds\":%d,\"tasks_total\":%lld,\"aborted_total\":%lld,\"gen_nodes\":%lld,\"task_nodes\":%lld,\"nodes\":%lld,\"max_task_nodes\":%lld,\"replay_fail\":%lld,\"final_cap\":%d,\"found\":%d,\"sec\":%.3f,\"witness\":[",
         bound.c_str(), cap, split, round, tasks_total, aborted_total, gen_nodes, tot, gen_nodes + tot, maxt, rfail, gcap.load(), found.w < (1 << 30) ? found.w : -1, now() - T0);
  for (size_t i = 0; i < found.wit.size(); i++) printf("%s[%d,%d]", i ? "," : "", found.wit[i].first, found.wit[i].second);
  printf("]}\n");
  return rfail ? 4 : 0;
}

int main(int argc, char** argv) {
  try { return main_impl(argc, argv); }
  catch (const invalid_argument& e) { fprintf(stderr, "invalid argument: %s\n", e.what()); return 2; }
  catch (const out_of_range& e) { fprintf(stderr, "out of range: %s\n", e.what()); return 2; }
  catch (const exception& e) { fprintf(stderr, "error: %s\n", e.what()); return 1; }
}
